### python

```python
# leetcode 435. 无重叠区间
n = int(input())
lines = []
for _ in range(n):
    x , y = map(int, input().split())
    left = x - y
    right = x + y
    lines.append((left, right))
lines.sort(key=lambda x: x[1])
ans = 0
now = -10**9
for left, right in lines:
    if left > now:
        ans += 1
        now = right
print(ans)
```
